(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-988":{scenario:{company:"Phương Nam Aero Technics",supervisor:{name:"Kiều Văn Thắng",role:{vi:"Trưởng ca bảo dưỡng ngoại trường (B1)",en:"Line Maintenance Shift Lead (B1)"}},ref_code:"WO-8812",title:{vi:"Đúng vật liệu gioăng. Đúng mô-men siết. Chỉ ký việc đã làm.",en:"Right seal material. Right torque. Sign only for work done."},brief:{vi:"Tàu mô phỏng KX-731 rò rỉ dầu tại khớp nối B-nut ống áp suất bơm số 2 của hệ thủy lực xanh. Bạn thay O-ring và siết lại khớp nối bằng cờ lê lực dài hiệu dụng 12 in có lắp đầu crowfoot thẳng trục dài 3 in; mô-men yêu cầu 360 in-lb (mô phỏng). Phiếu công việc nháp WO-8812 ghi vật liệu gioăng NBR và giá trị đặt trên cờ lê 360 in-lb. Dùng terminal tra dữ liệu, đối chiếu AMM/IPC đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"Training aircraft KX-731 leaks fluid at the B-nut of the pump 2 pressure line in the green hydraulic system. You replace the O-ring and re-torque the fitting with a torque wrench of 12 in effective length fitted with a 3 in inline crowfoot; required torque is 360 in-lb (training value). Draft work order WO-8812 lists seal material NBR and a wrench setting of 360 in-lb. Use the terminal, compare with the approved AMM/IPC, correct both fields and write an evidence-based report."},reference_title:{vi:"AMM/IPC chương 29 đã phê duyệt · WO-8812",en:"Approved AMM/IPC chapter 29 · WO-8812"},fields:[{id:"SEAL_MAT",label:{vi:"Vật liệu O-ring",en:"O-ring material"},initial:"NBR",expected:"EPR",choices:["NBR","EPR","FKM"],reference:"IPC 29-11 - danh mục phụ tùng",hint:{vi:"Kiểm tra loại dầu thủy lực của hệ: gioăng nitrile chỉ hợp với dầu gốc khoáng, không chịu được dầu phosphate ester.",en:"Check the system fluid: nitrile seals suit mineral oil only and cannot withstand phosphate ester fluid."}},{id:"TORQUE_SET",label:{vi:"Giá trị đặt trên cờ lê (in-lb)",en:"Wrench setting (in-lb)"},initial:"360",expected:"288",reference:"AMM 29-11 - bảng mô-men siết",ref_value:{vi:"Mô-men yêu cầu 360 in-lb; cờ lê L = 12 in; đầu crowfoot thẳng trục E = 3 in",en:"Required torque 360 in-lb; wrench L = 12 in; inline crowfoot E = 3 in"},hint:{vi:"Đầu nối thẳng trục làm dài cánh tay đòn: đặt nguyên 360 trên cờ lê sẽ siết quá lực.",en:"An inline extension lengthens the lever arm: setting 360 on the wrench will over-torque the fitting."}}],sop32:{vi:"Khi lắp đầu nối thẳng trục: giá trị đặt trên cờ lê = mô-men yêu cầu x L ÷ (L + E), với L là chiều dài hiệu dụng của cờ lê, E là chiều dài đầu nối; làm tròn đến 1 in-lb.",en:"With an inline extension: wrench setting = required torque x L ÷ (L + E), where L is the wrench effective length and E the extension length; round to 1 in-lb."},context:{label:"CMMS / WO-8812",metrics:[{label:{vi:"Mô-men yêu cầu",en:"Required torque"},value:"360 in-lb"},{label:{vi:"Cờ lê L / đầu nối E",en:"Wrench L / extension E"},value:"12 in / 3 in"},{label:{vi:"Dầu thủy lực hệ xanh",en:"Green system fluid"},value:"Phosphate ester type IV"}]},terminal:{system:"mx-term",settable:["SEAL_MAT","TORQUE_SET"],commands:[{cmd:"status",out:{vi:"WO-8812 đang mở: rò rỉ tại B-nut ống áp suất bơm số 2, hệ thủy lực xanh. Đã xả áp, gioăng cũ đã tháo. Tàu dự kiến khởi hành sau 40 phút.",en:"WO-8812 open: leak at the pump 2 pressure line B-nut, green hydraulic system. Pressure released, old seal removed. Departure planned in 40 minutes."}},{cmd:"cat fluid.spec",out:{vi:"Hệ thủy lực xanh: dầu gốc phosphate ester loại IV. Cấm dùng gioăng và dầu dành cho hệ gốc khoáng.",en:"Green hydraulic system: phosphate ester fluid type IV. Seals and fluids for mineral oil systems are prohibited."}},{cmd:"cat ipc-29-11.txt",out:{vi:"Mục 40: O-ring khớp nối áp suất, vật liệu EPR, tương thích phosphate ester. Loại NBR chỉ dùng cho hệ gốc khoáng, không lắp lẫn.",en:"Item 40: pressure fitting O-ring, EPR material, phosphate ester compatible. NBR type is for mineral oil systems only, not interchangeable."}},{cmd:"cat amm-29-11.txt",out:{vi:"Mô-men siết B-nut: 360 in-lb (mô phỏng). Khi dùng đầu nối dài, hiệu chỉnh giá trị đặt theo chiều dài cánh tay đòn.",en:"B-nut torque: 360 in-lb (training value). When an extension is used, correct the setting for the lever arm length."}},{cmd:"tool info tw-114",out:{vi:"Cờ lê lực TW-114: chiều dài hiệu dụng L = 12 in, còn hạn hiệu chuẩn. Đầu crowfoot CF-08 lắp thẳng trục, E = 3 in.",en:"Torque wrench TW-114: effective length L = 12 in, calibration valid. Crowfoot CF-08 fitted inline, E = 3 in."}},{cmd:"leak check",out:{vi:"Chưa thực hiện. Yêu cầu: chạy bơm số 2, giữ áp suất hệ thống 5 phút, xác nhận không rò rỉ trước khi ký CRS.",en:"Not done. Required: run pump 2, hold system pressure for 5 minutes and confirm no leak before signing the CRS."}}]},crisis:{vi:"Trưởng ca nhắn: “Tàu còn 40 phút là khởi hành. Kho chỉ còn gioăng NBR, cứ lắp tạm, đặt 360 cho nhanh rồi ký CRS luôn, chạy thử rò rỉ để chuyến về làm cũng được.”",en:"The shift lead texts: “Departure in 40 minutes. Stores only have NBR seals, fit one for now, set 360 to save time and sign the CRS, the leak check can wait for the return flight.”"},options:{safe:{vi:"Từ chối lắp gioăng NBR và ký CRS khi chưa kiểm tra rò rỉ; báo MCC và bộ phận chất lượng, đề nghị hoãn chuyến hoặc đổi tàu, ghi rõ tình trạng vào sổ kỹ thuật.",en:"Refuse to fit the NBR seal or sign the CRS before a leak check; inform MCC and Quality, request a delay or aircraft swap and record the status in the tech log."},shortcut:{vi:"Lắp gioăng NBR, đặt cờ lê 360 in-lb và ký CRS cho kịp giờ.",en:"Fit the NBR seal, set the wrench to 360 in-lb and sign the CRS to make the slot."},wait:{vi:"Bỏ dở công việc, để ca sau tự quyết.",en:"Leave the job unfinished and let the next shift decide."}},questions:{vi:["Vì sao phải dùng gioăng EPR thay cho NBR? Dữ liệu nào từ terminal và IPC chứng minh điều đó?","Trình bày cách hiệu chỉnh mô-men khi dùng đầu crowfoot và hậu quả nếu ký CRS trước khi kiểm tra rò rỉ."],en:["Why must an EPR seal be used instead of NBR? Which terminal and IPC data prove it?","Explain how you corrected the torque for the crowfoot and the consequences of signing the CRS before a leak check."]},hints:{vi:["Chạy lệnh tra loại dầu của hệ và đối chiếu với mục phụ tùng trong IPC trước khi chọn gioăng.","Lấy L và E từ thông tin dụng cụ rồi áp dụng công thức hiệu chỉnh ở SOP mục 3.2.","Đọc lại SOP mục 4.2: chỉ ký CRS cho công việc đã hoàn thành và kiểm tra theo tài liệu được phê duyệt."],en:["Run the command that shows the system fluid and compare it with the IPC item before choosing a seal.","Take L and E from the tool information, then apply the correction formula in SOP 3.2.","Re-read SOP 4.2: sign the CRS only for work completed and checked to approved data."]}},learning:{summary:{vi:"Kỹ sư bảo dưỡng máy bay hạng B1 (cơ khí, động cơ, điện cơ bản) và B2 (điện, điện tử hàng không) thực hiện, giám sát và ký chứng nhận cho phép khai thác (CRS) sau bảo dưỡng theo tài liệu được phê duyệt như AMM, IPC, TSM, MEL. Nghề đòi hỏi kỹ năng chẩn đoán, tuân thủ tuyệt đối tài liệu kỹ thuật, quản lý yếu tố con người và trung thực khi ký hồ sơ, vì mỗi chữ ký gắn trực tiếp với an toàn bay.",en:"B1 (mechanical, powerplant, basic electrical) and B2 (avionics and electrical) aircraft maintenance engineers perform, supervise and certify maintenance with a certificate of release to service (CRS) using approved data such as the AMM, IPC, TSM and MEL. The role requires diagnostic skill, strict adherence to technical data, human factors awareness and honesty in records, because every signature is tied directly to flight safety."},responsibilities:{vi:["Thực hiện kiểm tra trước chuyến, kiểm tra hằng ngày, hằng tuần và các gói bảo dưỡng định kỳ.","Chẩn đoán, khắc phục hỏng hóc theo AMM, sơ đồ hệ thống và hướng dẫn tìm lỗi (TSM).","Tra cứu IPC để chọn đúng phụ tùng, vật tư, kiểm tra hiệu lực áp dụng và khả năng lắp lẫn.","Áp dụng MEL để trì hoãn hỏng hóc đúng hạng mục, đúng thời hạn và thủ tục.","Ghi sổ kỹ thuật, ký CRS và lưu hồ sơ bảo dưỡng đầy đủ, chính xác."],en:["Perform pre-flight, daily and weekly checks and scheduled maintenance packages.","Troubleshoot and rectify defects using the AMM, system schematics and the TSM.","Use the IPC to select correct parts and materials and check effectivity and interchangeability.","Apply the MEL to defer defects in the right category, time limit and procedure.","Complete the tech log, sign the CRS and keep complete, accurate maintenance records."]},competencies:[{name:{vi:"Chẩn đoán hệ thống tàu bay",en:"Aircraft system troubleshooting"},desc:{vi:"Phân tích triệu chứng, đọc sơ đồ và cô lập hỏng hóc theo trình tự logic của TSM.",en:"Analyse symptoms, read schematics and isolate faults following the TSM logic."}},{name:{vi:"Tra cứu tài liệu kỹ thuật",en:"Technical data use"},desc:{vi:"Dùng đúng phiên bản AMM, IPC, MEL và kiểm tra hiệu lực áp dụng cho từng số tàu.",en:"Use the current AMM, IPC and MEL revision and check effectivity for each aircraft."}},{name:{vi:"Thực hành tiêu chuẩn",en:"Standard practices"},desc:{vi:"Siết đúng mô-men, khóa an toàn, chọn vật liệu tương thích và dùng dụng cụ còn hạn hiệu chuẩn.",en:"Apply correct torque and locking, choose compatible materials and use calibrated tools."}},{name:{vi:"Yếu tố con người",en:"Human factors"},desc:{vi:"Nhận diện áp lực thời gian, mệt mỏi, tự mãn và dừng lại khi điều kiện không an toàn.",en:"Recognise time pressure, fatigue and complacency and stop when conditions are unsafe."}},{name:{vi:"Trách nhiệm ký CRS",en:"CRS accountability"},desc:{vi:"Chỉ ký khi công việc đã hoàn thành, đã kiểm tra và hồ sơ phản ánh đúng thực tế.",en:"Sign only when work is complete, inspected and the records reflect reality."}}],knowledge:{vi:["EASA Part-66 về giấy phép kỹ sư bảo dưỡng các hạng A, B1, B2, C và phạm vi quyền ký.","EASA Part-145 về tổ chức bảo dưỡng được phê chuẩn và thủ tục ký CRS.","Hệ thống đánh số chương ATA (iSpec 2200) để tra cứu AMM, IPC, TSM, WDM.","Thực hành tiêu chuẩn: hiệu chỉnh mô-men khi dùng đầu nối, khóa an toàn, tương thích gioăng với dầu thủy lực.","Danh mục thiết bị tối thiểu (MEL) và các hạng mục trì hoãn A, B, C, D.","Yếu tố con người trong bảo dưỡng (Dirty Dozen) và hệ thống báo cáo an toàn tự nguyện."],en:["EASA Part-66 on A, B1, B2 and C maintenance licences and certification privileges.","EASA Part-145 on approved maintenance organisations and CRS procedures.","ATA chapter numbering (iSpec 2200) for navigating the AMM, IPC, TSM and WDM.","Standard practices: torque correction with extensions, safety locking and seal compatibility with hydraulic fluid.","The minimum equipment list (MEL) and deferral categories A, B, C and D.","Human factors in maintenance (the Dirty Dozen) and voluntary safety reporting."]},tools:["Cờ lê lực đã hiệu chuẩn & đầu crowfoot","Phần mềm quản lý bảo dưỡng (CMMS)","Tài liệu điện tử AMM/IPC/TSM","Đồng hồ vạn năng & thiết bị thử","Đèn soi & thiết bị NDT cơ bản"],kpis:{vi:["Tỷ lệ hỏng hóc lặp lại trong 10 chuyến sau khi khắc phục.","Tỷ lệ chậm chuyến do kỹ thuật trên 100 lần cất cánh.","Số phát hiện của kiểm tra chất lượng về hồ sơ và ký CRS (mục tiêu bằng 0).","Tỷ lệ công việc hoàn thành trong thời gian quay đầu tàu theo kế hoạch."],en:["Repeat defect rate within 10 flights after rectification.","Technical delays per 100 departures.","Quality audit findings on records and CRS signing (target zero).","Share of tasks completed within the planned turnaround time."]},day:[{time:"05:00",vi:"Nhận bàn giao ca, xem sổ kỹ thuật, hỏng hóc trì hoãn và kế hoạch tàu.",en:"Take the handover and review the tech log, deferred defects and the aircraft plan."},{time:"05:30",vi:"Kiểm tra trước chuyến: đi vòng quanh tàu, kiểm tra lốp, phanh, dầu và chất lỏng.",en:"Do pre-flight checks: walk-around, tyres, brakes, oil and fluid levels."},{time:"08:00",vi:"Khắc phục báo hỏng của tổ lái theo TSM, tra IPC để lấy đúng phụ tùng.",en:"Rectify a pilot report using the TSM and the IPC to get the right part."},{time:"11:00",vi:"Thực hiện gói kiểm tra hằng tuần, ký xác nhận từng bước công việc.",en:"Carry out the weekly check package and sign off each task step."},{time:"13:30",vi:"Hoàn thiện hồ sơ, ký CRS, bàn giao ca và báo cáo vấn đề an toàn.",en:"Complete records, sign the CRS, hand over and report safety concerns."}],mistakes:{vi:["Dùng gioăng hoặc vật tư không tương thích dầu thủy lực vì chỉ chọn theo hình dáng, kích thước.","Không hiệu chỉnh mô-men khi lắp đầu nối dài, gây siết quá lực, nứt hoặc biến dạng khớp nối.","Ký CRS hoặc ký hộ cho công việc chưa tự kiểm tra, chưa chạy thử rò rỉ."],en:["Using seals or materials incompatible with the hydraulic fluid because they look the same size.","Not correcting torque with an extension, over-tightening and cracking or deforming the fitting.","Signing the CRS or signing for others on work not inspected or leak tested."]},career:[{vi:"Kỹ thuật viên bảo dưỡng hạng A",en:"Category A maintenance technician"},{vi:"Kỹ sư bảo dưỡng B1/B2",en:"B1/B2 maintenance engineer"},{vi:"Kỹ sư ký CRS có năng định loại tàu",en:"Type-rated certifying engineer"},{vi:"Trưởng ca hoặc quản lý chất lượng bảo dưỡng",en:"Shift lead or maintenance quality manager"}],glossary:[{term:"CRS",vi:"Chứng nhận cho phép khai thác sau bảo dưỡng, ký bởi người có thẩm quyền.",en:"Certificate of release to service signed by authorised staff after maintenance."},{term:"AMM",vi:"Tài liệu hướng dẫn bảo dưỡng tàu bay của nhà sản xuất, gồm quy trình và giá trị kỹ thuật.",en:"Manufacturer's aircraft maintenance manual with procedures and technical values."},{term:"IPC",vi:"Danh mục phụ tùng minh họa, xác định số phụ tùng, hiệu lực và khả năng lắp lẫn.",en:"Illustrated parts catalogue that defines part numbers, effectivity and interchangeability."},{term:"MEL",vi:"Danh mục thiết bị tối thiểu cho phép khai thác khi một số thiết bị hỏng, kèm điều kiện, thời hạn.",en:"Minimum equipment list allowing dispatch with certain items inoperative under conditions and limits."},{term:"Crowfoot",vi:"Đầu nối dạng chân quạ lắp vào cờ lê lực để siết khớp nối ở vị trí khó tiếp cận.",en:"Open-end adapter fitted to a torque wrench to reach fittings in tight spaces."}],quiz:[{q:{vi:"Mô-men yêu cầu 300 in-lb, cờ lê L = 10 in, đầu nối thẳng trục E = 2 in. Giá trị đặt trên cờ lê là bao nhiêu?",en:"Required torque is 300 in-lb, wrench L = 10 in, inline extension E = 2 in. What is the wrench setting?"},options:{vi:["300 in-lb","360 in-lb","250 in-lb","240 in-lb"],en:["300 in-lb","360 in-lb","250 in-lb","240 in-lb"]},answer:2,explain:{vi:"Giá trị đặt = 300 x 10 ÷ (10 + 2) = 250 in-lb.",en:"300 x 10 ÷ (10 + 2) = 250 in-lb."}},{q:{vi:"Hệ thủy lực dùng dầu phosphate ester cần gioăng vật liệu nào?",en:"Which seal material suits a phosphate ester hydraulic system?"},options:{vi:["EPR","NBR","Cao su tự nhiên","Silicone thông dụng"],en:["EPR","NBR","Natural rubber","General silicone"]},answer:0,explain:{vi:"Gioăng EPR tương thích dầu phosphate ester; NBR dùng cho dầu gốc khoáng và sẽ trương nở, hỏng.",en:"EPR seals are compatible with phosphate ester; NBR is for mineral oil and will swell and fail."}},{q:{vi:"Trưởng ca yêu cầu ký CRS trước, để kiểm tra rò rỉ sau chuyến bay. Bạn làm gì?",en:"The shift lead asks you to sign the CRS now and leak check after the flight. What do you do?"},options:{vi:["Ký vì trưởng ca chịu trách nhiệm","Ký nhưng ghi chú vào sổ","Nhờ người khác ký thay","Từ chối, báo MCC và chất lượng, chỉ ký khi đã kiểm tra đạt"],en:["Sign because the lead is responsible","Sign but add a note in the log","Ask someone else to sign","Refuse, inform MCC and Quality and sign only after a passed check"]},answer:3,explain:{vi:"CRS xác nhận tàu đủ điều kiện bay; ký khi chưa kiểm tra là vi phạm nghiêm trọng an toàn và pháp luật.",en:"The CRS certifies airworthiness; signing before inspection is a serious safety and legal breach."}},{q:{vi:"Tài liệu nào xác định đúng số phụ tùng và khả năng lắp lẫn cho từng số tàu?",en:"Which document defines correct part numbers and interchangeability per aircraft?"},options:{vi:["AMM","IPC","MEL","Sổ tay khai thác bay"],en:["AMM","IPC","MEL","Flight operations manual"]},answer:1,explain:{vi:"IPC liệt kê số phụ tùng, hiệu lực áp dụng và quan hệ lắp lẫn; AMM mô tả quy trình bảo dưỡng.",en:"The IPC lists part numbers, effectivity and interchangeability; the AMM describes procedures."}}],tools_en:["Calibrated torque wrench & crowfoot adapters","Maintenance management software (CMMS)","Electronic AMM/IPC/TSM manuals","Multimeter & test equipment","Inspection light & basic NDT equipment"]}}})})(window.KKR);
